/** Figma 픽셀아트를 그대로 옮긴 데이터. 한 칸 = (x, y, w, h) 격자 단위 + 팔레트 번호. */
class Px(val x: Float, val y: Float, val w: Float, val h: Float, val c: Int)

private fun parseSemi(s: String) = s.split(';').map { r -> r.split(',').let { Px(it[0].toFloat(), it[1].toFloat(), it[2].toFloat(), it[3].toFloat(), it[4].toInt()) } }
private fun parseSpace(s: String) = s.split(',').map { r -> r.trim().split(' ').let { Px(it[0].toFloat(), it[1].toFloat(), it[2].toFloat(), it[3].toFloat(), it[4].toInt()) } }

fun DrawScope.drawPx(list: List<Px>, pal: List<Color>, unit: Float, ox: Float, oy: Float, alpha: Float = 1f, dx: Float = 0f, dy: Float = 0f) {
    for (p in list) {
        val c = pal[p.c]
        drawRect(c.copy(alpha = c.alpha * alpha), Offset(ox + dx + p.x * unit, oy + dy + p.y * unit), Size(p.w * unit, p.h * unit))
    }
}

